import sys

input = sys.stdin.read
data = input().split()

n, m, r, k = map(int, data)

if r > n or r > m:
    print(0.0)
else:
    x = min(n - r + 1, k)
    y = min(m - r + 1, k)
    ans = 0.0
    for i in range(x + 1):
        for j in range(y + 1):
            if i * j <= k and (x - i) * (y - j) <= k:
                ans = max(ans, i * j + (x - i) * (y - j) + max(0, k - i * j - (x - i) * (y - j)) * 2.0)
    print(ans)
